const D = { density: .5, energy: .6, speed: 1, scale: 1, hue: 40, x: .5, y: .5, style: 'chalk', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, u = Math.min(W, H), diag = Math.sqrt(W*W + H*H);
const cxp = P.x*W, cyp = P.y*H;
const PI = Math.PI, HP = PI/2, TAU = PI*2;
const SD = P.seed|0;

function h2(a,b,g){ let n=(a*374761393 + b*668265263 + g*2246822519 + SD*3266489917)|0; n=(n^(n>>13))*1274126177|0; return ((n^(n>>16))>>>0)/4294967295; }
// 4-fold reflective-symmetric Truchet bit (mirror across x=0,y=0 flips the tile type)
function tbit(i,j,g){ const fi=i>=0?i:-1-i, fj=j>=0?j:-1-j, sx=i>=0?0:1, sy=j>=0?0:1; return ((h2(fi,fj,g)>0.5?1:0) ^ sx ^ sy); }
function twoArcs(b,X,Y,c){ if(b===0){ arc(X,Y,c,c,0,HP); arc(X+c,Y+c,c,c,PI,PI+HP); } else { arc(X+c,Y,c,c,HP,PI); arc(X,Y+c,c,c,-HP,0); } }
function hb2rgb(h,s,v){ h=((h%360)+360)%360; s/=100; v/=100; const c=v*s, x=c*(1-Math.abs((h/60)%2-1)), m=v-c; let r,g,b; if(h<60){r=c;g=x;b=0;}else if(h<120){r=x;g=c;b=0;}else if(h<180){r=0;g=c;b=x;}else if(h<240){r=0;g=x;b=c;}else if(h<300){r=x;g=0;b=c;}else{r=c;g=0;b=x;} return [r+m,g+m,b+m]; }

const style = P.style;
const opaque = P.alpha >= 99.5;
const aMul = opaque ? 1 : Math.max(0, P.alpha/100);

// ---------- cached ground (radial rangoli ground) ----------
const GW = Math.max(360, Math.min(720, Math.round(W/2.4))), GH = Math.max(60, Math.round(GW*H/W));
const gkey = GW+'x'+GH+'|'+style+'|'+Math.round(P.hue/6);
if (opaque && (!S.gnd || S.gkey !== gkey)) {
  if (!S.gnd || S.gw!==GW || S.gh!==GH){ S.gnd = createGraphics(GW,GH); S.gnd.pixelDensity(1); S.gw=GW; S.gh=GH; }
  const g=S.gnd; g.loadPixels(); const px=g.pixels;
  let iH,iS,iV,eH,eS,eV;
  if (style==='ink'){ iH=45;iS=9;iV=93; eH=42;eS=16;eV=80; }
  else if (style==='rangoli'){ iH=P.hue;iS=48;iV=27; eH=(P.hue+325)%360;eS=72;eV=7; }
  else if (style==='neon'){ iH=(P.hue+210)%360;iS=62;iV=13; eH=(P.hue+210)%360;eS=82;eV=3; }
  else if (style==='gold'){ iH=38;iS=58;iV=15; eH=26;eS=78;eV=3; }
  else { iH=P.hue;iS=36;iV=29; eH=(P.hue+210)%360;eS=60;eV=8; } // chalk
  const iC=hb2rgb(iH,iS,iV), eC=hb2rgb(eH,eS,eV);
  const gcx=GW*0.5, gcy=GH*0.5, gr=Math.sqrt(gcx*gcx+gcy*gcy);
  for(let j=0;j<GH;j++) for(let i=0;i<GW;i++){
    const dx=i-gcx, dy=j-gcy; let t=Math.min(1, Math.sqrt(dx*dx+dy*dy)/gr); t=t*t*(3-2*t);
    const o=4*(j*GW+i);
    px[o]  =255*(iC[0]+(eC[0]-iC[0])*t);
    px[o+1]=255*(iC[1]+(eC[1]-iC[1])*t);
    px[o+2]=255*(iC[2]+(eC[2]-iC[2])*t);
    px[o+3]=255;
  }
  g.updatePixels(); S.gkey=gkey;
}

// ---------- geometry ----------
const dens = Math.max(.15, Math.min(1, P.density));
const Ndens = Math.round(3.5 + (dens-.15)/.85*5.5);           // ~4..9 loops across
const cell = (0.82*u/Ndens) * Math.max(.5, Math.min(2, P.scale));
const extent = diag*1.06;
const N = Math.min(22, Math.max(4, Math.ceil(extent/cell)));
const Nh = Math.ceil(N/2);
const R = cell*0.5;
const maxR = extent*0.5;

// ---------- clock / reveal / regeneration ----------
const spd = Math.max(0, Math.min(3, P.speed));
const tt = Math.max(0, K.t);
const PERIOD = 15;
const cyc = tt/PERIOD, gen = Math.floor(cyc), local = cyc-gen;
let r = Math.min(1, local/0.75); r = r*r*(3-2*r);            // reveal 0..1
const revR = r*maxR*1.12, front = R*1.4;
const rot = tt*(0.014 + 0.02*spd) + A.mid*0.03;

const hueEff = P.hue + K.section*6 + tt*0.25;                 // slow palette drift across sections
const energyEff = Math.min(1.2, Math.max(.15, P.energy) * (0.8 + 0.35*K.intensity + A.rms*0.5));
const shimSpd = 0.55 + spd*0.5 + A.treble*1.2;
const aNorm = Math.min(1.3, 11/N);
const gG = 20*energyEff*aNorm*aMul;
const gC = 52*energyEff*Math.min(1.3, aNorm*1.05)*aMul;

push();
if (opaque && S.gnd) image(S.gnd, 0, 0, W, H);
translate(cxp, cyp); rotate(rot);
strokeCap(ROUND); noFill();
if (style==='ink' || !opaque) blendMode(BLEND); else blendMode(ADD);

// ---------- loops (progressive radial reveal; old gen fades behind the front) ----------
for(let i=-Nh;i<Nh;i++) for(let j=-Nh;j<Nh;j++){
  const ccx=(i+0.5)*cell, ccy=(j+0.5)*cell, rc=Math.sqrt(ccx*ccx+ccy*ccy);
  if(rc>maxR*1.16) continue;
  const rr=rc/maxR, ang=Math.atan2(ccy,ccx);
  const shim=0.72+0.42*Math.sin(ang*2 - tt*shimSpd + rr*4.0);
  const X=i*cell, Y=j*cell;
  let g_, bright, fb;
  if(rc<=revR){ g_=gen; bright=1; fb=(rc>revR-front)?1.7:1.0; }
  else { g_=gen-1; bright=0; fb=1; }
  const dim = bright?1:(0.5+0.5*(1-r));
  const b=tbit(i,j,g_);
  let gh,gs,gv,ch,cs,cv;
  if(style==='rangoli'){ const hh=(hueEff+ang*85+rr*140)%360; gh=hh;gs=92;gv=82; ch=hh;cs=80;cv=100; }
  else if(style==='neon'){ const hh=((((i+j)&1)?hueEff:hueEff+165)%360); gh=hh;gs=96;gv=85; ch=hh;cs=85;cv=100; }
  else if(style==='gold'){ const spec=0.5+0.5*Math.cos(ang-tt*0.5); gh=40;gs=82;gv=58; ch=45;cs=52;cv=Math.min(100,72+34*spec); }
  else if(style==='ink'){ ch=((hueEff%360)+360)%360;cs=28;cv=14; }
  else { const hh=((hueEff%360)+360)%360; gh=hh;gs=70;gv=92; ch=hh;cs=12;cv=99; } // chalk
  if(style!=='ink'){
    const gw=Math.max(2, cell*0.17*(0.7+0.5*energyEff));
    const ga=Math.min(58, gG*shim*dim*fb);
    strokeWeight(gw); stroke(gh,gs,gv,ga); twoArcs(b,X,Y,cell);
  }
  const cw=Math.max(1.1, cell*0.05*(0.75+0.5*energyEff));
  const ca=Math.min(92, gC*(0.82+0.32*shim)*dim*fb);
  strokeWeight(cw); stroke(ch,cs,cv,ca); twoArcs(b,X,Y,cell);
}

// ---------- pulli dots (always present, breathe on beat/bass) ----------
const dPulse = 0.82 + 0.3*K.swell + 0.5*A.bass;
const dR = Math.max(1.4, R*0.2);
noStroke();
for(let i=-Nh;i<=Nh;i++) for(let j=-Nh;j<=Nh;j++){
  const X=i*cell, Y=j*cell, rc=Math.sqrt(X*X+Y*Y);
  if(rc>maxR*1.16) continue;
  if(style==='ink'){ fill(((hueEff%360)+360)%360,26,16,90*aMul); circle(X,Y,dR*1.15); continue; }
  const ang=Math.atan2(Y,X);
  let dh,ds;
  if(style==='rangoli'){ dh=(hueEff+ang*85+rc/maxR*140)%360; ds=82; }
  else if(style==='neon'){ dh=(((i+j)&1)?hueEff:hueEff+165)%360; ds=90; }
  else if(style==='gold'){ dh=45; ds=70; }
  else { dh=((hueEff%360)+360)%360; ds=62; }
  fill(dh,ds,100, Math.min(52, 32*energyEff*aNorm*aMul)*dPulse); circle(X,Y, dR*2.6*dPulse);
  fill(dh, style==='chalk'?16:46, 100, Math.min(95,70*aMul)); circle(X,Y, dR*1.0);
}

blendMode(BLEND);
pop();
